import Image from "next/image";

import { getHomePageData } from "@/services/strapi"; // Importamos nuestra función

// Convertimos el componente en async para poder pedir datos
export default async function Home() {
  
  // 1. Llamamos a los datos
  const strapiData = await getHomePageData();

  // 2. Un console.log para que veas en tu TERMINAL (donde corre npm run dev) qué llega
  //console.log("Datos recibidos de Strapi:", JSON.stringify(strapiData, null, 2));

  // Si no hay datos, mostramos un aviso simple (útil si Strapi está apagado)
  if (!strapiData) {
    return <div>No se pudieron cargar los datos. Revisa que Strapi esté corriendo.</div>;
  }

  // 3. Renderizamos
  // Nota: strapiData tiene tus campos. Si pusiste un titulo en la homepage:
  const { blocks } = strapiData;

  return (
    <main className="p-10">
      <h1 className="text-4xl font-bold mb-4">Conectado con Strapi</h1>
      
      {/* Mostramos el título base de la página */}
      <h2 className="text-2xl text-blue-600 mb-8">Título desde Strapi: {title}</h2>

      {/* Aquí veremos qué bloques llegaron (solo texto por ahora para depurar) */}
      <div className="bg-gray-100 p-4 rounded">
        <h3 className="font-bold text-black">Bloques encontrados (Dynamic Zone):</h3>
        <pre className="text-black">{JSON.stringify(blocks, null, 2)}</pre>
      </div>
    </main>
  );
}